import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum VersionType {
  BUDGET = 'Budget',
  SOP = 'S&OP'
}

export enum ForecastStatus {
  DRAFT = 'Draft',
  SUBMITTED = 'Submitted',
  APPROVED = 'Approved',
  ARCHIVED = 'Archived'
}

export interface ForecastRecord {
  id: string;
  section: string; // Trader or Broker
  client: string;
  country: string;
  product: string;
  category: string;
  month: number;
  year: number;
  version: VersionType;
  qty: number;
  sales: number;
  gp: number;
  salesPerson: string;
  salesPersonEmail: string;
  status: ForecastStatus;
}

export interface AuditLog {
  id: string;
  timestamp: string;
  userEmail: string;
  recordId: string;
  product: string;
  actionType: 'AMEND' | 'DELETE' | 'SUBMIT';
  reasonCode: string;
  details: string;
}

export interface User {
  email: string;
  name: string;
  role: 'Admin' | 'Sales';
}

export interface BudgetRatio {
  salesPerMT: number;
  gpPerMT: number;
}

import { ForecastRecord, VersionType, ForecastStatus } from '../types';

const CLIENTS = ['Alpha Corp', 'Beta Industries', 'Gamma Logistics'];
const PRODUCTS = ['Steel Coils', 'Aluminum Sheets', 'Copper Wire', 'Plastic Resins'];
const SECTIONS = ['Trader', 'Broker'];

export const generateMockData = (): ForecastRecord[] => {
  const data: ForecastRecord[] = [];
  const currentYear = new Date().getFullYear();

  let idCounter = 1;

  CLIENTS.forEach(client => {
    PRODUCTS.forEach(product => {
      // Create data for first 6 months
      for (let month = 1; month <= 6; month++) {
        const baseQty = Math.floor(Math.random() * 100) + 50;
        const pricePerUnit = Math.floor(Math.random() * 20) + 100;
        const gpMargin = 0.2; // 20% margin

        // 1. Budget Version (The Baseline)
        data.push({
          id: `rec-${idCounter++}`,
          section: SECTIONS[Math.floor(Math.random() * SECTIONS.length)],
          client,
          country: 'USA',
          product,
          category: 'Raw Materials',
          month,
          year: currentYear,
          version: VersionType.BUDGET,
          qty: baseQty,
          sales: baseQty * pricePerUnit,
          gp: baseQty * pricePerUnit * gpMargin,
          salesPerson: 'John Doe',
          salesPersonEmail: 'john.doe@company.com',
          status: ForecastStatus.APPROVED
        });

        // 2. S&OP Version (Editable) - Starts same as budget usually
        data.push({
          id: `rec-${idCounter++}`,
          section: SECTIONS[0], // Simplified for matching
          client,
          country: 'USA',
          product,
          category: 'Raw Materials',
          month,
          year: currentYear,
          version: VersionType.SOP,
          qty: baseQty, // Initially same as budget
          sales: baseQty * pricePerUnit,
          gp: baseQty * pricePerUnit * gpMargin,
          salesPerson: 'John Doe',
          salesPersonEmail: 'john.doe@company.com',
          status: ForecastStatus.DRAFT
        });
      }
    });
  });

  return data;
};

import { GoogleGenAI } from "@google/genai";
import { AuditLog } from "../types";

// Helper to summarize audit logs for the AI
const formatLogsForPrompt = (logs: AuditLog[]) => {
  return logs.map(log => 
    `- ${log.actionType} on ${log.product}: ${log.details} (Reason: ${log.reasonCode})`
  ).join('\n');
};

export const analyzeChanges = async (logs: AuditLog[]): Promise<string> => {
  if (!process.env.API_KEY) {
    return "API Key not configured. Unable to generate AI insights.";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const logSummary = formatLogsForPrompt(logs);

  const prompt = `
    You are a Supply Chain analyst assistant. 
    Review the following audit log of changes made to the monthly demand forecast.
    Provide a concise, professional summary (max 3 sentences) of the net impact and any potential risks (e.g., significant quantity reductions or unusual reasons).

    Audit Logs:
    ${logSummary}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "No insights generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Unable to generate insights due to an API error.";
  }
};

