export default SelectionScreen;

import React, { useState, useMemo } from 'react';
import { ForecastRecord, VersionType, BudgetRatio, AuditLog, ForecastStatus } from '../types';
import { Edit2, Save, XCircle, Trash2, ArrowLeft, CheckCircle } from 'lucide-react';

interface Props {
  data: ForecastRecord[];
  client: string;
  section: string;
  currentUserEmail: string;
  onUpdateData: (records: ForecastRecord[], auditLogs: AuditLog[]) => void;
  onBack: () => void;
  onSubmit: () => void;
}

const REASONS = [
  'Market Downturn',
  'Supply Chain Disruption',
  'New Business Won',
  'Customer Request',
  'Correction'
];

const ReviewScreen: React.FC<Props> = ({ 
  data, 
  client, 
  section, 
  currentUserEmail, 
  onUpdateData, 
  onBack, 
  onSubmit 
}) => {
  // Local state for the filtered view
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editQty, setEditQty] = useState<number>(0);
  const [editReason, setEditReason] = useState<string>('');

  // Filter for relevant data
  const filteredData = useMemo(() => {
    return data.filter(d => d.client === client && d.section === section);
  }, [data, client, section]);

  // Calculate Budget Ratios (Sales per MT, GP per MT) for each product
  // Key: Product Name -> Ratio Object
  const budgetRatios = useMemo(() => {
    const ratios = new Map<string, BudgetRatio>();

    // Group budget items by product
    const budgetItems = filteredData.filter(d => d.version === VersionType.BUDGET);
    const productGroups = new Map<string, { totalQty: number, totalSales: number, totalGP: number }>();

    budgetItems.forEach(item => {
      const current = productGroups.get(item.product) || { totalQty: 0, totalSales: 0, totalGP: 0 };
      current.totalQty += item.qty;
      current.totalSales += item.sales;
      current.totalGP += item.gp;
      productGroups.set(item.product, current);
    });

    productGroups.forEach((totals, product) => {
      if (totals.totalQty > 0) {
        ratios.set(product, {
          salesPerMT: totals.totalSales / totals.totalQty,
          gpPerMT: totals.totalGP / totals.totalQty
        });
      }
    });

    return ratios;
  }, [filteredData]);

  // Sort: Product -> Month
  const sortedDisplayData = useMemo(() => {
    return [...filteredData].sort((a, b) => {
      if (a.product !== b.product) return a.product.localeCompare(b.product);
      if (a.version !== b.version) return a.version === VersionType.SOP ? -1 : 1; // Show SOP first
      return a.month - b.month;
    });
  }, [filteredData]);

  // Actions
  const startEdit = (record: ForecastRecord) => {
    setEditingId(record.id);
    setEditQty(record.qty);
    setEditReason('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditQty(0);
    setEditReason('');
  };

  const handleSave = () => {
    if (!editingId || !editReason) {
      alert("Please select a Reason Code before saving.");
      return;
    }

    const record = data.find(d => d.id === editingId);
    if (!record) return;

    const ratio = budgetRatios.get(record.product) || { salesPerMT: 0, gpPerMT: 0 };

    // Recalculate based on Budget Logic
    const newSales = editQty * ratio.salesPerMT;
    const newGP = editQty * ratio.gpPerMT;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: editQty,
      sales: newSales,
      gp: newGP,
      status: ForecastStatus.DRAFT // Keep as draft until final submit
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'AMEND',
      reasonCode: editReason,
      details: `Qty changed from ${record.qty} to ${editQty}. Sales/GP recalculated.`
    };

    // Update global state
    const newData = data.map(d => d.id === editingId ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);

    cancelEdit();
  };

  const handleDelete = (record: ForecastRecord) => {
    const reason = prompt("Select reason for deletion (Simulated dropdown):\n" + REASONS.join(', '));
    if (!reason) return;

    // Logic: "Delete" in forecast usually means setting to 0 or marking inactive. 
    // We will set Qty to 0 and recalc.

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: 0,
      sales: 0,
      gp: 0,
      status: ForecastStatus.ARCHIVED
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'DELETE',
      reasonCode: reason,
      details: `Record cleared/soft-deleted. Previous Qty: ${record.qty}`
    };

    const newData = data.map(d => d.id === record.id ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-10 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-slate-800">{client}</h1>
            <p className="text-sm text-slate-500">Section: {section} | Reviewing S&OP Versions</p>
          </div>
        </div>
        <button
          onClick={onSubmit}
          className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg font-semibold flex items-center gap-2 shadow-sm transition-colors"
        >
          <CheckCircle className="h-5 w-5" />
          Finish & Submit
        </button>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 overflow-auto max-w-[100vw]">
        <div className="bg-white rounded-xl shadow border border-slate-200 overflow-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-100 text-slate-600 text-xs uppercase font-semibold">
              <tr>
                <th className="p-4 border-b">Product</th>
                <th className="p-4 border-b">Period</th>
                <th className="p-4 border-b">Version</th>
                <th className="p-4 border-b text-right">Qty (MT)</th>
                <th className="p-4 border-b text-right">Sales</th>
                <th className="p-4 border-b text-right">GP</th>
                <th className="p-4 border-b">Status</th>
                <th className="p-4 border-b text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm text-slate-700">
              {sortedDisplayData.map((row) => {
                const isEditing = editingId === row.id;
                const isSOP = row.version === VersionType.SOP;
                const isBudget = row.version === VersionType.BUDGET;

                return (
                  <tr 
                    key={row.id} 
                    className={`hover:bg-slate-50 transition-colors ${isBudget ? 'bg-slate-50/50 text-slate-500 italic' : ''}`}
                  >
                    <td className="p-4 font-medium">{row.product}</td>
                    <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>
                    <td className="p-4">
                      <span className={`px-2 py-1 rounded text-xs font-bold ${isBudget ? 'bg-slate-200' : 'bg-blue-100 text-blue-700'}`}>
                        {row.version}
                      </span>
                    </td>

                    {/* Qty Column */}
                    <td className="p-4 text-right font-mono">
                      {isEditing ? (
                        <input
                          type="number"
                          value={editQty}
                          onChange={(e) => setEditQty(Number(e.target.value))}
                          className="w-24 px-2 py-1 border border-blue-400 rounded focus:ring-2 focus:ring-blue-200 outline-none text-right"
                        />
                      ) : (
                        row.qty.toLocaleString()
                      )}
                    </td>

                    <td className="p-4 text-right">{formatCurrency(row.sales)}</td>
                    <td className="p-4 text-right">{formatCurrency(row.gp)}</td>

                    <td className="p-4">
                      <span className={`px-2 py-1 rounded-full text-xs ${
                        row.status === ForecastStatus.ARCHIVED ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
                      }`}>
                        {row.status}
                      </span>
                    </td>

                    {/* Actions Column */}
                    <td className="p-4 flex justify-center gap-2">
                      {isEditing ? (
                        <div className="flex items-center gap-2 bg-white p-1 rounded shadow-lg border absolute right-12 z-20">
                           <select 
                            value={editReason}
                            onChange={(e) => setEditReason(e.target.value)}
                            className="text-xs p-1 border rounded w-32"
                           >
                             <option value="">Select Reason...</option>
                             {REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                           </select>
                           <button onClick={handleSave} className="p-1 hover:bg-green-100 text-green-600 rounded"><Save size={16}/></button>
                           <button onClick={cancelEdit} className="p-1 hover:bg-red-100 text-red-600 rounded"><XCircle size={16}/></button>
                        </div>
                      ) : (
                        isSOP && row.status !== ForecastStatus.ARCHIVED && (
                          <>
                            <button 
                              onClick={() => startEdit(row)} 
                              className="p-1.5 hover:bg-blue-100 text-blue-600 rounded transition-colors"
                              title="Amend Forecast"
                            >
                              <Edit2 size={16} />
                            </button>
                            <button 
                              onClick={() => handleDelete(row)} 
                              className="p-1.5 hover:bg-red-100 text-red-600 rounded transition-colors"
                              title="Delete Record"
                            >
                              <Trash2 size={16} />
                            </button>
                          </>
                        )
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {sortedDisplayData.length === 0 && (
            <div className="p-10 text-center text-slate-400">
              No records found for this client/section selection.
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ReviewScreen;

import React, { useState } from 'react';
import { AuditLog } from '../types';
import { Check, ClipboardList, RefreshCw, Sparkles } from 'lucide-react';
import { analyzeChanges } from '../services/geminiService';

interface Props {
  auditLogs: AuditLog[];
  onReset: () => void;
}

const ConfirmationScreen: React.FC<Props> = ({ auditLogs, onReset }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);

  const handleAIAnalysis = async () => {
    setAnalyzing(true);
    const result = await analyzeChanges(auditLogs);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-lg border border-slate-200 w-full max-w-3xl overflow-hidden">
        <div className="bg-green-600 p-6 text-center">
          <div className="mx-auto w-16 h-16 bg-green-500 rounded-full flex items-center justify-center mb-4">
            <Check className="text-white h-8 w-8" />
          </div>
          <h2 className="text-2xl font-bold text-white">Review Completed</h2>
          <p className="text-green-100 mt-2">Your changes have been staged for the backend patch.</p>
        </div>

        <div className="p-8">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
              <ClipboardList className="h-5 w-5 text-slate-500" />
              Session Audit Trail
            </h3>

            <button 
              onClick={handleAIAnalysis}
              disabled={analyzing || auditLogs.length === 0}
              className="text-xs flex items-center gap-1 bg-purple-100 text-purple-700 px-3 py-1 rounded-full hover:bg-purple-200 transition"
            >
              {analyzing ? (
                <span className="w-3 h-3 border-2 border-purple-600 border-t-transparent rounded-full animate-spin"></span>
              ) : (
                <Sparkles size={14} />
              )}
              {aiAnalysis ? 'Regenerate Analysis' : 'Analyze with Gemini'}
            </button>
          </div>

          {/* AI Analysis Result */}
          {aiAnalysis && (
             <div className="mb-6 bg-purple-50 p-4 rounded-lg border border-purple-100 text-sm text-purple-800 animate-in fade-in slide-in-from-top-4">
               <strong className="block mb-1 font-semibold">Gemini Insight:</strong>
               {aiAnalysis}
             </div>
          )}

          <div className="bg-slate-50 rounded-lg border border-slate-200 max-h-64 overflow-y-auto mb-8">
            {auditLogs.length === 0 ? (
              <div className="p-4 text-center text-slate-500 italic">No changes made in this session.</div>
            ) : (
              <table className="w-full text-sm text-left">
                <thead className="bg-slate-100 text-slate-600 font-semibold sticky top-0">
                  <tr>
                    <th className="p-3">Product</th>
                    <th className="p-3">Action</th>
                    <th className="p-3">Details</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-200">
                  {auditLogs.map((log) => (
                    <tr key={log.id}>
                      <td className="p-3 font-medium">{log.product}</td>
                      <td className="p-3">
                        <span className={`px-2 py-0.5 rounded text-xs font-bold ${
