import React, { useState, useEffect } from 'react';
import { User, ForecastRecord, AuditLog } from './types';
import { generateMockData } from './services/mockData';
import LoginScreen from './components/LoginScreen';
import SelectionScreen from './components/SelectionScreen';
import ReviewScreen from './components/ReviewScreen';
import ConfirmationScreen from './components/ConfirmationScreen';

enum AppStep {
  LOGIN,
  SELECTION,
  REVIEW,
  CONFIRMATION
}

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.LOGIN);
  const [user, setUser] = useState<User | null>(null);

  // "Database" state
  const [data, setData] = useState<ForecastRecord[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]); // All logs
  const [sessionLogs, setSessionLogs] = useState<AuditLog[]>([]); // Logs for current workflow

  // Selection state
  const [selectedClient, setSelectedClient] = useState('');
  const [selectedSection, setSelectedSection] = useState('');

  // Initialize Data
  useEffect(() => {
    setData(generateMockData());
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setStep(AppStep.SELECTION);
  };

  const handleSelection = (client: string, section: string) => {
    setSelectedClient(client);
    setSelectedSection(section);
    setSessionLogs([]); // Reset session logs for new client
    setStep(AppStep.REVIEW);
  };

  const handleDataUpdate = (updatedRecords: ForecastRecord[], newLogs: AuditLog[]) => {
    setData(updatedRecords);
    setAuditLogs(prev => [...prev, ...newLogs]);
    setSessionLogs(prev => [...prev, ...newLogs]);
  };

  const handleSubmit = () => {
    // Here is where the actual PATCH to Dataverse/Excel would happen.
    // console.log("Patching data...", sessionLogs);
    setStep(AppStep.CONFIRMATION);
  };

  const handleReset = () => {
    setSelectedClient('');
    setSelectedSection('');
    setSessionLogs([]);
    setStep(AppStep.SELECTION);
  };

  // Render logic based on step
  switch (step) {
    case AppStep.LOGIN:
      return <LoginScreen onLogin={handleLogin} />;

    case AppStep.SELECTION:
      return (
        <SelectionScreen 
          data={data} 
          userEmail={user?.email || ''} 
          onProceed={handleSelection} 
        />
      );

    case AppStep.REVIEW:
      return (
        <ReviewScreen
          data={data}
          client={selectedClient}
          section={selectedSection}
          currentUserEmail={user?.email || 'unknown'}
          onUpdateData={handleDataUpdate}
          onBack={() => setStep(AppStep.SELECTION)}
          onSubmit={handleSubmit}
        />
      );

    case AppStep.CONFIRMATION:
      return (
        <ConfirmationScreen 
          auditLogs={sessionLogs}
          onReset={handleReset}
        />
      );

    default:
      return <div>Error: Unknown Step</div>;
  }
};

export default App;

