    const productGroups = new Map<string, { totalQty: number, totalSales: number, totalGP: number }>();

    budgetItems.forEach(item => {
      const current = productGroups.get(item.product) || { totalQty: 0, totalSales: 0, totalGP: 0 };
      current.totalQty += item.qty;
      current.totalSales += item.sales;
      current.totalGP += item.gp;
      productGroups.set(item.product, current);
    });

    productGroups.forEach((totals, product) => {
      if (totals.totalQty > 0) {
        ratios.set(product, {
          salesPerMT: totals.totalSales / totals.totalQty,
          gpPerMT: totals.totalGP / totals.totalQty
        });
      }
    });

    return ratios;
  }, [filteredData]);

  // Separate and Sort Data
  const sopData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.SOP)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  const budgetData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.BUDGET)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  // Actions
  const startEdit = (record: ForecastRecord) => {
    setEditingId(record.id);
    setEditQty(record.qty);
    setEditReason('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditQty(0);
    setEditReason('');
  };

  const handleSave = () => {
    if (!editingId || !editReason) {
      alert("Please select a Reason Code before saving.");
      return;
    }

    const record = data.find(d => d.id === editingId);
    if (!record) return;

    const ratio = budgetRatios.get(record.product) || { salesPerMT: 0, gpPerMT: 0 };

    // Recalculate based on Budget Logic
    const newSales = editQty * ratio.salesPerMT;
    const newGP = editQty * ratio.gpPerMT;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: editQty,
      sales: newSales,
      gp: newGP,
      status: ForecastStatus.DRAFT // Keep as draft until final submit
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'AMEND',
      reasonCode: editReason,
      details: `Qty changed from ${record.qty} to ${editQty}. Sales/GP recalculated.`
    };

    // Update global state
    const newData = data.map(d => d.id === editingId ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);

    cancelEdit();
  };

  const handleDelete = (record: ForecastRecord) => {
    const reason = prompt("Select reason for deletion (Simulated dropdown):\n" + REASONS.join(', '));
    if (!reason) return;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: 0,
      sales: 0,
      gp: 0,
      status: ForecastStatus.ARCHIVED
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'DELETE',
      reasonCode: reason,
      details: `Record cleared/soft-deleted. Previous Qty: ${record.qty}`
    };

    const newData = data.map(d => d.id === record.id ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-10 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-slate-800">{client}</h1>
            <p className="text-sm text-slate-500">Section: {section}</p>
          </div>
        </div>
        <button
          onClick={onSubmit}
          className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg font-semibold flex items-center gap-2 shadow-sm transition-colors"
        >
          <CheckCircle className="h-5 w-5" />
          Finish & Submit
        </button>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 overflow-auto max-w-[100vw] space-y-8">

        {/* S&OP Section */}
        <div className="space-y-4">
           <div className="flex items-center gap-2 text-lg font-bold text-blue-800">
             <TrendingUp className="h-5 w-5" />
             <h2>Working Forecast (S&OP)</h2>
             <span className="text-xs font-normal text-blue-600 bg-blue-100 px-2 py-0.5 rounded-full">Editable</span>
           </div>

           <div className="bg-white rounded-xl shadow border border-blue-100 overflow-hidden">
             <table className="w-full text-left border-collapse">
               <thead className="bg-blue-50 text-blue-800 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-blue-100">Product</th>
                   <th className="p-4 border-b border-blue-100">Period</th>
                   <th className="p-4 border-b border-blue-100 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-blue-100 text-right">Sales</th>
                   <th className="p-4 border-b border-blue-100 text-right">GP</th>
                   <th className="p-4 border-b border-blue-100">Status</th>
                   <th className="p-4 border-b border-blue-100 text-center">Actions</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100 text-sm text-slate-700">
                 {sopData.map((row) => {
                   const isEditing = editingId === row.id;

                   return (
                     <tr key={row.id} className="hover:bg-slate-50 transition-colors">
                       <td className="p-4 font-medium text-slate-900">{row.product}</td>
                       <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>

                       {/* Qty Column */}
                       <td className="p-4 text-right font-mono">
                         {isEditing ? (
                           <input
                             type="number"
                             value={editQty}
                             onChange={(e) => setEditQty(Number(e.target.value))}
                             className="w-24 px-2 py-1 border border-blue-400 rounded focus:ring-2 focus:ring-blue-200 outline-none text-right"
                           />
                         ) : (
                           <span className="font-semibold">{row.qty.toLocaleString()}</span>
                         )}
                       </td>

                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.sales)}</td>
                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.gp)}</td>

                       <td className="p-4">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                           row.status === ForecastStatus.ARCHIVED ? 'bg-red-100 text-red-700' : 
                           row.status === ForecastStatus.APPROVED ? 'bg-green-100 text-green-700' :
                           'bg-yellow-100 text-yellow-700'
                         }`}>
                           {row.status}
                         </span>
                       </td>

                       {/* Actions Column */}
                       <td className="p-4 flex justify-center gap-2 relative">
                         {isEditing ? (
                           <div className="flex items-center gap-2 bg-white p-2 rounded-lg shadow-xl border border-slate-200 absolute right-12 z-20 -top-2">
                              <div className="flex flex-col">
                                <label className="text-[10px] text-slate-400 font-semibold mb-1 uppercase">Reason Code</label>
                                <select 
                                 value={editReason}
                                 onChange={(e) => setEditReason(e.target.value)}
                                 className="text-xs p-1.5 border border-slate-300 rounded w-40 outline-none focus:border-blue-500"
                                >
                                  <option value="">Select Reason...</option>
                                  {REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                                </select>
                              </div>
                              <div className="flex gap-1 mt-4">
                                <button onClick={handleSave} className="p-1.5 bg-green-50 hover:bg-green-100 text-green-700 rounded border border-green-200" title="Save"><Save size={14}/></button>
                                <button onClick={cancelEdit} className="p-1.5 bg-red-50 hover:bg-red-100 text-red-700 rounded border border-red-200" title="Cancel"><XCircle size={14}/></button>
                              </div>
                           </div>
                         ) : (
                           row.status !== ForecastStatus.ARCHIVED && (
                             <>
                               <button 
                                 onClick={() => startEdit(row)} 
                                 className="p-1.5 hover:bg-blue-50 text-blue-600 rounded transition-colors"
                                 title="Amend Forecast"
                               >
                                 <Edit2 size={16} />
                               </button>
                               <button 
                                 onClick={() => handleDelete(row)} 
                                 className="p-1.5 hover:bg-red-50 text-red-600 rounded transition-colors"
                                 title="Delete Record"
                               >
                                 <Trash2 size={16} />
                               </button>
                             </>
                           )
                         )}
                       </td>
                     </tr>
                   );
                 })}
                 {sopData.length === 0 && (
                   <tr>
                     <td colSpan={7} className="p-8 text-center text-slate-400 italic">No S&OP records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

        {/* Budget Section */}
        <div className="space-y-4">
           <div className="flex items-center gap-2 text-lg font-bold text-slate-600">
             <BookOpen className="h-5 w-5" />
             <h2>Budget Baseline</h2>
             <span className="text-xs font-normal text-slate-500 bg-slate-200 px-2 py-0.5 rounded-full">Reference Only</span>
           </div>

           <div className="bg-slate-50 rounded-xl border border-slate-200 overflow-hidden opacity-90">
             <table className="w-full text-left border-collapse">
               <thead className="bg-slate-100 text-slate-500 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-slate-200">Product</th>
                   <th className="p-4 border-b border-slate-200">Period</th>
                   <th className="p-4 border-b border-slate-200 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-slate-200 text-right">Sales</th>
                   <th className="p-4 border-b border-slate-200 text-right">GP</th>
                   <th className="p-4 border-b border-slate-200">Status</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-200 text-sm text-slate-600">
                 {budgetData.map((row) => (
                   <tr key={row.id}>
                     <td className="p-4 font-medium">{row.product}</td>
                     <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>
                     <td className="p-4 text-right font-mono">{row.qty.toLocaleString()}</td>
                     <td className="p-4 text-right">{formatCurrency(row.sales)}</td>
                     <td className="p-4 text-right">{formatCurrency(row.gp)}</td>
                     <td className="p-4">
                       <span className="px-2 py-1 rounded-full text-xs font-medium bg-slate-200 text-slate-600">
                         {row.status}
                       </span>
                     </td>
                   </tr>
                 ))}
                 {budgetData.length === 0 && (
                   <tr>
                     <td colSpan={6} className="p-8 text-center text-slate-400 italic">No Budget records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

      </div>
    </div>
  );
};

export default ReviewScreen;

import React, { useState, useMemo } from 'react';
import { ForecastRecord, VersionType, BudgetRatio, AuditLog, ForecastStatus } from '../types';
import { Edit2, Save, XCircle, Trash2, ArrowLeft, CheckCircle, TrendingUp, BookOpen, Plus, Calendar } from 'lucide-react';

interface Props {
  data: ForecastRecord[];
  client: string;
  section: string;
  currentUserEmail: string;
  onUpdateData: (records: ForecastRecord[], auditLogs: AuditLog[]) => void;
  onBack: () => void;
  onSubmit: () => void;
}

const REASONS = [
  'Market Downturn',
  'Supply Chain Disruption',
  'New Business Won',
  'Customer Request',
  'Correction'
];

const ReviewScreen: React.FC<Props> = ({ 
  data, 
  client, 
  section, 
  currentUserEmail, 
  onUpdateData, 
  onBack, 
  onSubmit 
}) => {
  // Local state for editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editQty, setEditQty] = useState<number>(0);
  const [editReason, setEditReason] = useState<string>('');

  // Local state for adding
  const [isAdding, setIsAdding] = useState(false);
  const [newRecord, setNewRecord] = useState<{
    product: string;
    month: number;
    year: number;
    qty: number;
    manualSales?: number;
    manualGP?: number;
  }>({
    product: '',
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
    qty: 0
  });

  // Filter for relevant data
  const filteredData = useMemo(() => {
    return data.filter(d => d.client === client && d.section === section);
  }, [data, client, section]);

  // Derived lists for dropdowns
  const availableProducts = useMemo(() => Array.from(new Set(data.map(d => d.product))).sort(), [data]);
  const availableYears = useMemo(() => {
    const years = Array.from(new Set(data.map(d => d.year))).sort();
    return years.length ? years : [new Date().getFullYear()];
  }, [data]);

  // Calculate Budget Ratios (Sales per MT, GP per MT) for each product based on THIS CLIENT'S history
  const budgetRatios = useMemo(() => {
    const ratios = new Map<string, BudgetRatio>();

    const budgetItems = filteredData.filter(d => d.version === VersionType.BUDGET);
    const productGroups = new Map<string, { totalQty: number, totalSales: number, totalGP: number }>();

    budgetItems.forEach(item => {
      const current = productGroups.get(item.product) || { totalQty: 0, totalSales: 0, totalGP: 0 };
      current.totalQty += item.qty;
      current.totalSales += item.sales;
      current.totalGP += item.gp;
      productGroups.set(item.product, current);
    });

    productGroups.forEach((totals, product) => {
      if (totals.totalQty > 0) {
        ratios.set(product, {
          salesPerMT: totals.totalSales / totals.totalQty,
          gpPerMT: totals.totalGP / totals.totalQty
        });
      }
    });

    return ratios;
  }, [filteredData]);

  // Separate and Sort Data
  const sopData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.SOP)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  const budgetData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.BUDGET)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  // Actions
  const startEdit = (record: ForecastRecord) => {
    setEditingId(record.id);
    setEditQty(record.qty);
    setEditReason('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditQty(0);
    setEditReason('');
  };

  const handleSave = () => {
    if (!editingId || !editReason) {
      alert("Please select a Reason Code before saving.");
      return;
    }

    const record = data.find(d => d.id === editingId);
    if (!record) return;

    const ratio = budgetRatios.get(record.product) || { salesPerMT: 0, gpPerMT: 0 };

    // Recalculate based on Budget Logic if available, else keep ratio or warn
    // For simplicity, if editing existing, we rely on ratio. If ratio is 0, we might need to keep old price? 
    // Let's assume ratio exists or fallback to current implied price.
    const currentPrice = record.qty > 0 ? record.sales / record.qty : 0;
    const currentGPMargin = record.qty > 0 ? record.gp / record.qty : 0;

    const usedPrice = ratio.salesPerMT || currentPrice;
    const usedGP = ratio.gpPerMT || currentGPMargin;

    const newSales = editQty * usedPrice;
    const newGP = editQty * usedGP;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: editQty,
      sales: newSales,
      gp: newGP,
      status: ForecastStatus.DRAFT
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'AMEND',
      reasonCode: editReason,
      details: `Qty changed from ${record.qty} to ${editQty}.`
    };

    const newData = data.map(d => d.id === editingId ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);

    cancelEdit();
  };

  const handleDelete = (record: ForecastRecord) => {
    const reason = prompt("Select reason for deletion (Simulated dropdown):\n" + REASONS.join(', '));
    if (!reason) return;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: 0,
      sales: 0,
      gp: 0,
      status: ForecastStatus.ARCHIVED
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'DELETE',
      reasonCode: reason,
      details: `Record cleared/soft-deleted. Previous Qty: ${record.qty}`
    };

    const newData = data.map(d => d.id === record.id ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);
  };

  // NEW: Handle Add Logic
  const handleAddNew = () => {
    if (!newRecord.product) { alert("Select a product"); return; }
    if (newRecord.qty <= 0) { alert("Qty > 0 required"); return; }

    const ratio = budgetRatios.get(newRecord.product);
    const hasBudget = ratio && ratio.salesPerMT > 0;

    let finalSales = 0;
    let finalGP = 0;

    if (hasBudget) {
      finalSales = newRecord.qty * ratio.salesPerMT;
      finalGP = newRecord.qty * ratio.gpPerMT;
    } else {
      finalSales = newRecord.manualSales || 0;
      finalGP = newRecord.manualGP || 0;
    }

    const newId = `new-${Date.now()}`;
    const newEntry: ForecastRecord = {
      id: newId,
      client,
      section,
      country: filteredData[0]?.country || 'Unknown',
      product: newRecord.product,
      category: filteredData.find(d => d.product === newRecord.product)?.category || 'General',
      month: newRecord.month,
      year: newRecord.year,
      version: VersionType.SOP,
      qty: newRecord.qty,
      sales: finalSales,
      gp: finalGP,
      salesPerson: filteredData[0]?.salesPerson || 'Unknown',
      salesPersonEmail: currentUserEmail,
      status: ForecastStatus.DRAFT
    };

    const log: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: newId,
      product: newRecord.product,
      actionType: 'AMEND', // effectively adding is an amendment to the plan
      reasonCode: 'New Business', 
      details: `Added new record. Qty: ${newEntry.qty}`
    };

    onUpdateData([...data, newEntry], [log]);

    // Reset form
    setNewRecord({ ...newRecord, qty: 0, manualSales: 0, manualGP: 0 });
    setIsAdding(false);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  // Check if selected product in Add Form has budget
  const selectedProductHasBudget = useMemo(() => {
    if (!newRecord.product) return true; // default hidden
    const r = budgetRatios.get(newRecord.product);
    return !!(r && r.salesPerMT > 0);
  }, [newRecord.product, budgetRatios]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-10 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-slate-800">{client}</h1>
            <p className="text-sm text-slate-500">Section: {section}</p>
          </div>
        </div>
        <button
          onClick={onSubmit}
          className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg font-semibold flex items-center gap-2 shadow-sm transition-colors"
        >
          <CheckCircle className="h-5 w-5" />
          Finish & Submit
        </button>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 overflow-auto max-w-[100vw] space-y-8">

        {/* S&OP Section */}
        <div className="space-y-4">
           <div className="flex justify-between items-end">
             <div className="flex items-center gap-2 text-lg font-bold text-blue-800">
               <TrendingUp className="h-5 w-5" />
               <h2>Working Forecast (S&OP)</h2>
               <span className="text-xs font-normal text-blue-600 bg-blue-100 px-2 py-0.5 rounded-full">Editable</span>
             </div>

             {!isAdding && (
               <button 
                 onClick={() => setIsAdding(true)}
                 className="text-sm flex items-center gap-1 bg-blue-600 text-white px-3 py-1.5 rounded-lg hover:bg-blue-700 transition shadow-sm"
               >
                 <Plus size={16} /> Add Forecast
               </button>
             )}
           </div>

           {/* Add New Record Form */}
           {isAdding && (
             <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 animate-in fade-in slide-in-from-top-2">
                <div className="flex justify-between items-start mb-3">
                  <h3 className="text-sm font-bold text-blue-900 flex items-center gap-2">
                    <Plus size={14} /> New Entry
                  </h3>
                  <button onClick={() => setIsAdding(false)} className="text-slate-400 hover:text-slate-600"><XCircle size={18}/></button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-5 gap-4 items-end">
                   <div>
                     <label className="block text-xs font-semibold text-blue-800 mb-1">Product</label>
                     <select 
                       value={newRecord.product}
                       onChange={e => setNewRecord({...newRecord, product: e.target.value})}
                       className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                     >
                       <option value="">Select Product...</option>
                       {availableProducts.map(p => <option key={p} value={p}>{p}</option>)}
                     </select>
                   </div>

                   <div className="flex gap-2">
                      <div className="w-2/3">
                        <label className="block text-xs font-semibold text-blue-800 mb-1">Month</label>
                        <select 
                          value={newRecord.month}
                          onChange={e => setNewRecord({...newRecord, month: Number(e.target.value)})}
                          className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                        >
                          {Array.from({length: 12}, (_, i) => i + 1).map(m => (
                            <option key={m} value={m}>{new Date(2000, m-1, 1).toLocaleString('default', {month:'short'})}</option>
                          ))}
                        </select>
                      </div>
                      <div className="w-1/3">
                        <label className="block text-xs font-semibold text-blue-800 mb-1">Year</label>
                        <select 
                          value={newRecord.year}
                          onChange={e => setNewRecord({...newRecord, year: Number(e.target.value)})}
                          className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                        >
                          {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                      </div>
                   </div>

                   <div>
                     <label className="block text-xs font-semibold text-blue-800 mb-1">Quantity (MT)</label>
                     <input 
                       type="number" 
                       value={newRecord.qty}
                       onChange={e => setNewRecord({...newRecord, qty: Number(e.target.value)})}
                       className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                       placeholder="0"
                     />
                   </div>

                   {/* Dynamic Sales/GP fields if no budget */}
                   {!selectedProductHasBudget && (
                     <>
                      <div>
                        <label className="block text-xs font-semibold text-orange-700 mb-1">Est. Sales ($)</label>
                        <input 
                          type="number"
                          value={newRecord.manualSales || ''}
                          onChange={e => setNewRecord({...newRecord, manualSales: Number(e.target.value)})} 
                          className="w-full text-sm p-2 border border-orange-300 bg-orange-50 rounded focus:border-orange-500 outline-none"
                          placeholder="No budget found"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-semibold text-orange-700 mb-1">Est. GP ($)</label>
                        <input 
                          type="number"
                          value={newRecord.manualGP || ''}
                          onChange={e => setNewRecord({...newRecord, manualGP: Number(e.target.value)})} 
                          className="w-full text-sm p-2 border border-orange-300 bg-orange-50 rounded focus:border-orange-500 outline-none"
                          placeholder="No budget found"
                        />
                      </div>
                     </>
                   )}

                   {selectedProductHasBudget && (
                      <div className="col-span-2 flex items-center h-full pb-2">
                        <span className="text-xs text-green-600 bg-green-50 px-2 py-1 rounded border border-green-200">
                          Budget pricing applied automatically
                        </span>
                      </div>
                   )}

                   <div>
                     <button 
                       onClick={handleAddNew}
                       className="w-full bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold py-2 px-4 rounded shadow transition"
                     >
                       Add Entry
                     </button>
                   </div>
                </div>
             </div>
           )}

           <div className="bg-white rounded-xl shadow border border-blue-100 overflow-hidden">
             <table className="w-full text-left border-collapse">
               <thead className="bg-blue-50 text-blue-800 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-blue-100">Product</th>
                   <th className="p-4 border-b border-blue-100">Period</th>
                   <th className="p-4 border-b border-blue-100 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-blue-100 text-right">Sales</th>
                   <th className="p-4 border-b border-blue-100 text-right">GP</th>
                   <th className="p-4 border-b border-blue-100">Status</th>
                   <th className="p-4 border-b border-blue-100 text-center">Actions</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100 text-sm text-slate-700">
                 {sopData.map((row) => {
                   const isEditing = editingId === row.id;

                   return (
                     <tr key={row.id} className="hover:bg-slate-50 transition-colors">
                       <td className="p-4 font-medium text-slate-900">{row.product}</td>
                       <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>

                       {/* Qty Column */}
                       <td className="p-4 text-right font-mono">
                         {isEditing ? (
                           <input
                             type="number"
                             value={editQty}
                             onChange={(e) => setEditQty(Number(e.target.value))}
                             className="w-24 px-2 py-1 border border-blue-400 rounded focus:ring-2 focus:ring-blue-200 outline-none text-right"
                           />
                         ) : (
                           <span className="font-semibold">{row.qty.toLocaleString()}</span>
                         )}
                       </td>

                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.sales)}</td>
                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.gp)}</td>

                       <td className="p-4">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                           row.status === ForecastStatus.ARCHIVED ? 'bg-red-100 text-red-700' : 
                           row.status === ForecastStatus.APPROVED ? 'bg-green-100 text-green-700' :
                           'bg-yellow-100 text-yellow-700'
                         }`}>
                           {row.status}
                         </span>
                       </td>

                       {/* Actions Column */}
                       <td className="p-4 flex justify-center gap-2 relative">
                         {isEditing ? (
                           <div className="flex items-center gap-2 bg-white p-2 rounded-lg shadow-xl border border-slate-200 absolute right-12 z-20 -top-2">
                              <div className="flex flex-col">
                                <label className="text-[10px] text-slate-400 font-semibold mb-1 uppercase">Reason Code</label>
                                <select 
                                 value={editReason}
                                 onChange={(e) => setEditReason(e.target.value)}
                                 className="text-xs p-1.5 border border-slate-300 rounded w-40 outline-none focus:border-blue-500"
                                >
                                  <option value="">Select Reason...</option>
                                  {REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                                </select>
                              </div>
                              <div className="flex gap-1 mt-4">
                                <button onClick={handleSave} className="p-1.5 bg-green-50 hover:bg-green-100 text-green-700 rounded border border-green-200" title="Save"><Save size={14}/></button>
                                <button onClick={cancelEdit} className="p-1.5 bg-red-50 hover:bg-red-100 text-red-700 rounded border border-red-200" title="Cancel"><XCircle size={14}/></button>
                              </div>
                           </div>
                         ) : (
                           row.status !== ForecastStatus.ARCHIVED && (
                             <>
                               <button 
                                 onClick={() => startEdit(row)} 
                                 className="p-1.5 hover:bg-blue-50 text-blue-600 rounded transition-colors"
                                 title="Amend Forecast"
                               >
                                 <Edit2 size={16} />
                               </button>
                               <button 
                                 onClick={() => handleDelete(row)} 
                                 className="p-1.5 hover:bg-red-50 text-red-600 rounded transition-colors"
                                 title="Delete Record"
                               >
                                 <Trash2 size={16} />
                               </button>
                             </>
                           )
                         )}
                       </td>
                     </tr>
                   );
                 })}
                 {sopData.length === 0 && (
                   <tr>
                     <td colSpan={7} className="p-8 text-center text-slate-400 italic">No S&OP records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

        {/* Budget Section */}
        <div className="space-y-4">
           <div className="flex items-center gap-2 text-lg font-bold text-slate-600">
             <BookOpen className="h-5 w-5" />
             <h2>Budget Baseline</h2>
             <span className="text-xs font-normal text-slate-500 bg-slate-200 px-2 py-0.5 rounded-full">Reference Only</span>
           </div>

           <div className="bg-slate-50 rounded-xl border border-slate-200 overflow-hidden opacity-90">
             <table className="w-full text-left border-collapse">
               <thead className="bg-slate-100 text-slate-500 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-slate-200">Product</th>
                   <th className="p-4 border-b border-slate-200">Period</th>
                   <th className="p-4 border-b border-slate-200 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-slate-200 text-right">Sales</th>
                   <th className="p-4 border-b border-slate-200 text-right">GP</th>
                   <th className="p-4 border-b border-slate-200">Status</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-200 text-sm text-slate-600">
                 {budgetData.map((row) => (
                   <tr key={row.id}>
                     <td className="p-4 font-medium">{row.product}</td>
                     <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>
                     <td className="p-4 text-right font-mono">{row.qty.toLocaleString()}</td>
                     <td className="p-4 text-right">{formatCurrency(row.sales)}</td>
                     <td className="p-4 text-right">{formatCurrency(row.gp)}</td>
                     <td className="p-4">
                       <span className="px-2 py-1 rounded-full text-xs font-medium bg-slate-200 text-slate-600">
                         {row.status}
                       </span>
                     </td>
                   </tr>
                 ))}
                 {budgetData.length === 0 && (
                   <tr>
                     <td colSpan={6} className="p-8 text-center text-slate-400 italic">No Budget records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

      </div>
    </div>
  );
};

export default ReviewScreen;

import React, { useState, useMemo } from 'react';
import { ForecastRecord, VersionType, BudgetRatio, AuditLog, ForecastStatus } from '../types';
import { Edit2, Save, XCircle, Trash2, ArrowLeft, CheckCircle, TrendingUp, BookOpen, Plus, Calendar, DollarSign, Package, Percent, BarChart3, ArrowUp, ArrowDown, Minus } from 'lucide-react';

interface Props {
  data: ForecastRecord[];
  client: string;
  section: string;
  currentUserEmail: string;
  onUpdateData: (records: ForecastRecord[], auditLogs: AuditLog[]) => void;
  onBack: () => void;
  onSubmit: () => void;
}

const REASONS = [
  'Market Downturn',
  'Supply Chain Disruption',
  'New Business Won',
  'Customer Request',
  'Correction'
];

const ReviewScreen: React.FC<Props> = ({ 
  data, 
  client, 
  section, 
  currentUserEmail, 
  onUpdateData, 
  onBack, 
  onSubmit 
}) => {
  // Local state for editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editQty, setEditQty] = useState<number>(0);
  const [editReason, setEditReason] = useState<string>('');

  // Local state for adding
  const [isAdding, setIsAdding] = useState(false);
  const [newRecord, setNewRecord] = useState<{
    product: string;
    month: number;
    year: number;
    qty: number;
    manualSales?: number;
    manualGP?: number;
  }>({
    product: '',
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
    qty: 0
  });

  // Filter for relevant data
  const filteredData = useMemo(() => {
    return data.filter(d => d.client === client && d.section === section);
  }, [data, client, section]);

  // Derived lists for dropdowns
  const availableProducts = useMemo(() => Array.from(new Set(data.map(d => d.product))).sort(), [data]);
  const availableYears = useMemo(() => {
    const years = Array.from(new Set(data.map(d => d.year))).sort();
    return years.length ? years : [new Date().getFullYear()];
  }, [data]);

  // Calculate Budget Ratios (Sales per MT, GP per MT) for each product based on THIS CLIENT'S history
  const budgetRatios = useMemo(() => {
    const ratios = new Map<string, BudgetRatio>();

    const budgetItems = filteredData.filter(d => d.version === VersionType.BUDGET);
    const productGroups = new Map<string, { totalQty: number, totalSales: number, totalGP: number }>();

    budgetItems.forEach(item => {
      const current = productGroups.get(item.product) || { totalQty: 0, totalSales: 0, totalGP: 0 };
      current.totalQty += item.qty;
      current.totalSales += item.sales;
      current.totalGP += item.gp;
      productGroups.set(item.product, current);
    });

    productGroups.forEach((totals, product) => {
      if (totals.totalQty > 0) {
        ratios.set(product, {
          salesPerMT: totals.totalSales / totals.totalQty,
          gpPerMT: totals.totalGP / totals.totalQty
        });
      }
    });

    return ratios;
  }, [filteredData]);

  // Separate and Sort Data
  const sopData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.SOP)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  const budgetData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.BUDGET)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  // --- KPI CALCULATIONS ---
  const kpiStats = useMemo(() => {
    const calculateMetrics = (dataset: ForecastRecord[]) => {
      const totalQty = dataset.reduce((sum, item) => sum + item.qty, 0);
      const totalSales = dataset.reduce((sum, item) => sum + item.sales, 0);
      const totalGP = dataset.reduce((sum, item) => sum + item.gp, 0);
      return {
        qty: totalQty,
        sales: totalSales,
        gp: totalGP,
        gpPercent: totalSales > 0 ? (totalGP / totalSales) * 100 : 0,
        avgPrice: totalQty > 0 ? totalSales / totalQty : 0
      };
    };

    const current = calculateMetrics(sopData);
    const baseline = calculateMetrics(budgetData);

    return { current, baseline };
  }, [sopData, budgetData]);

  const renderKPICard = (
    title: string, 
    icon: React.ReactNode, 
    value: string, 
    currentRaw: number, 
    baselineRaw: number,
    isPercentage: boolean = false
  ) => {
    const isPositive = currentRaw >= baselineRaw;
    const diff = currentRaw - baselineRaw;
    const achievement = baselineRaw !== 0 
      ? Math.round((currentRaw / baselineRaw) * 100) 
      : (currentRaw > 0 ? 100 : 0);

    // For formatting trend text
    const trendColor = isPositive ? 'text-green-600' : 'text-red-600';
    const TrendIcon = isPositive ? ArrowUp : ArrowDown;
    const neutral = baselineRaw === 0;

    return (
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-between">
        <div className="flex justify-between items-start mb-2">
          <div className="text-slate-500 text-xs font-semibold uppercase tracking-wide">{title}</div>
          <div className={`p-1.5 rounded-lg ${isPositive ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
            {icon}
          </div>
        </div>
        <div>
          <div className="text-2xl font-bold text-slate-800">{value}</div>
          {!neutral ? (
             <div className={`flex items-center gap-1 text-xs font-medium mt-1 ${trendColor}`}>
               <TrendIcon size={12} strokeWidth={3} />
               <span>{achievement}% of Budget</span>
             </div>
          ) : (
            <div className="text-xs text-slate-400 mt-1 flex items-center gap-1">
              <Minus size={12} /> No Budget
            </div>
          )}
        </div>
      </div>
    );
  };
  // ------------------------

  // Actions
  const startEdit = (record: ForecastRecord) => {
    setEditingId(record.id);
    setEditQty(record.qty);
    setEditReason('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditQty(0);
    setEditReason('');
  };

  const handleSave = () => {
    if (!editingId || !editReason) {
      alert("Please select a Reason Code before saving.");
      return;
    }

    const record = data.find(d => d.id === editingId);
    if (!record) return;

    const ratio = budgetRatios.get(record.product) || { salesPerMT: 0, gpPerMT: 0 };

    // Recalculate based on Budget Logic if available, else keep ratio or warn
    const currentPrice = record.qty > 0 ? record.sales / record.qty : 0;
    const currentGPMargin = record.qty > 0 ? record.gp / record.qty : 0;

    const usedPrice = ratio.salesPerMT || currentPrice;
    const usedGP = ratio.gpPerMT || currentGPMargin;

    const newSales = editQty * usedPrice;
    const newGP = editQty * usedGP;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: editQty,
      sales: newSales,
      gp: newGP,
      status: ForecastStatus.DRAFT
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'AMEND',
      reasonCode: editReason,
      details: `Qty changed from ${record.qty} to ${editQty}.`
    };

    const newData = data.map(d => d.id === editingId ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);

    cancelEdit();
  };

  const handleDelete = (record: ForecastRecord) => {
    const reason = prompt("Select reason for deletion (Simulated dropdown):\n" + REASONS.join(', '));
    if (!reason) return;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: 0,
      sales: 0,
      gp: 0,
      status: ForecastStatus.ARCHIVED
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'DELETE',
      reasonCode: reason,
      details: `Record cleared/soft-deleted. Previous Qty: ${record.qty}`
    };

    const newData = data.map(d => d.id === record.id ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);
  };

  // NEW: Handle Add Logic
  const handleAddNew = () => {
    if (!newRecord.product) { alert("Select a product"); return; }
    if (newRecord.qty <= 0) { alert("Qty > 0 required"); return; }

    const ratio = budgetRatios.get(newRecord.product);
    const hasBudget = ratio && ratio.salesPerMT > 0;

    let finalSales = 0;
    let finalGP = 0;

    if (hasBudget) {
      finalSales = newRecord.qty * ratio.salesPerMT;
      finalGP = newRecord.qty * ratio.gpPerMT;
    } else {
      finalSales = newRecord.manualSales || 0;
      finalGP = newRecord.manualGP || 0;
    }

    const newId = `new-${Date.now()}`;
    const newEntry: ForecastRecord = {
      id: newId,
      client,
      section,
      country: filteredData[0]?.country || 'Unknown',
      product: newRecord.product,
      category: filteredData.find(d => d.product === newRecord.product)?.category || 'General',
      month: newRecord.month,
      year: newRecord.year,
      version: VersionType.SOP,
      qty: newRecord.qty,
      sales: finalSales,
      gp: finalGP,
      salesPerson: filteredData[0]?.salesPerson || 'Unknown',
      salesPersonEmail: currentUserEmail,
      status: ForecastStatus.DRAFT
    };

    const log: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: newId,
      product: newRecord.product,
      actionType: 'AMEND', // effectively adding is an amendment to the plan
      reasonCode: 'New Business', 
      details: `Added new record. Qty: ${newEntry.qty}`
    };

    onUpdateData([...data, newEntry], [log]);

    // Reset form
    setNewRecord({ ...newRecord, qty: 0, manualSales: 0, manualGP: 0 });
    setIsAdding(false);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  const formatNumber = (val: number) => {
    return new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(val);
  };

  // Check if selected product in Add Form has budget
  const selectedProductHasBudget = useMemo(() => {
    if (!newRecord.product) return true; // default hidden
    const r = budgetRatios.get(newRecord.product);
    return !!(r && r.salesPerMT > 0);
  }, [newRecord.product, budgetRatios]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-10 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-slate-800">{client}</h1>
            <p className="text-sm text-slate-500">Section: {section}</p>
          </div>
        </div>
        <button
          onClick={onSubmit}
          className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg font-semibold flex items-center gap-2 shadow-sm transition-colors"
        >
          <CheckCircle className="h-5 w-5" />
          Finish & Submit
        </button>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 overflow-auto max-w-[100vw] space-y-8">

        {/* KPI Dashboard */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 animate-in fade-in slide-in-from-top-4 duration-500">
          {renderKPICard(
            "Total Revenue", 
            <DollarSign size={18} />, 
            formatCurrency(kpiStats.current.sales), 
            kpiStats.current.sales, 
            kpiStats.baseline.sales
          )}
          {renderKPICard(
            "Total Volume (MT)", 
            <Package size={18} />, 
            formatNumber(kpiStats.current.qty), 
            kpiStats.current.qty, 
            kpiStats.baseline.qty
          )}
          {renderKPICard(
            "Gross Margin %", 
            <Percent size={18} />, 
            `${kpiStats.current.gpPercent.toFixed(1)}%`, 
            kpiStats.current.gpPercent, 
            kpiStats.baseline.gpPercent,
            true
          )}
          {renderKPICard(
            "Avg. Price / MT", 
            <BarChart3 size={18} />, 
            formatCurrency(kpiStats.current.avgPrice), 
            kpiStats.current.avgPrice, 
            kpiStats.baseline.avgPrice
          )}
        </div>

        {/* S&OP Section */}
        <div className="space-y-4">
           <div className="flex justify-between items-end">
             <div className="flex items-center gap-2 text-lg font-bold text-blue-800">
               <TrendingUp className="h-5 w-5" />
               <h2>Working Forecast (S&OP)</h2>
               <span className="text-xs font-normal text-blue-600 bg-blue-100 px-2 py-0.5 rounded-full">Editable</span>
             </div>

             {!isAdding && (
               <button 
                 onClick={() => setIsAdding(true)}
                 className="text-sm flex items-center gap-1 bg-blue-600 text-white px-3 py-1.5 rounded-lg hover:bg-blue-700 transition shadow-sm"
               >
                 <Plus size={16} /> Add Forecast
               </button>
             )}
           </div>

           {/* Add New Record Form */}
           {isAdding && (
             <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 animate-in fade-in slide-in-from-top-2">
                <div className="flex justify-between items-start mb-3">
                  <h3 className="text-sm font-bold text-blue-900 flex items-center gap-2">
                    <Plus size={14} /> New Entry
                  </h3>
                  <button onClick={() => setIsAdding(false)} className="text-slate-400 hover:text-slate-600"><XCircle size={18}/></button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-5 gap-4 items-end">
                   <div>
                     <label className="block text-xs font-semibold text-blue-800 mb-1">Product</label>
                     <select 
                       value={newRecord.product}
                       onChange={e => setNewRecord({...newRecord, product: e.target.value})}
                       className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                     >
                       <option value="">Select Product...</option>
                       {availableProducts.map(p => <option key={p} value={p}>{p}</option>)}
                     </select>
                   </div>

                   <div className="flex gap-2">
                      <div className="w-2/3">
                        <label className="block text-xs font-semibold text-blue-800 mb-1">Month</label>
                        <select 
                          value={newRecord.month}
                          onChange={e => setNewRecord({...newRecord, month: Number(e.target.value)})}
                          className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                        >
                          {Array.from({length: 12}, (_, i) => i + 1).map(m => (
                            <option key={m} value={m}>{new Date(2000, m-1, 1).toLocaleString('default', {month:'short'})}</option>
                          ))}
                        </select>
                      </div>
                      <div className="w-1/3">
                        <label className="block text-xs font-semibold text-blue-800 mb-1">Year</label>
                        <select 
                          value={newRecord.year}
                          onChange={e => setNewRecord({...newRecord, year: Number(e.target.value)})}
                          className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                        >
                          {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                      </div>
                   </div>

                   <div>
                     <label className="block text-xs font-semibold text-blue-800 mb-1">Quantity (MT)</label>
                     <input 
                       type="number" 
                       value={newRecord.qty}
                       onChange={e => setNewRecord({...newRecord, qty: Number(e.target.value)})}
                       className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                       placeholder="0"
                     />
                   </div>

                   {/* Dynamic Sales/GP fields if no budget */}
                   {!selectedProductHasBudget && (
                     <>
                      <div>
                        <label className="block text-xs font-semibold text-orange-700 mb-1">Est. Sales ($)</label>
                        <input 
                          type="number"
                          value={newRecord.manualSales || ''}
                          onChange={e => setNewRecord({...newRecord, manualSales: Number(e.target.value)})} 
                          className="w-full text-sm p-2 border border-orange-300 bg-orange-50 rounded focus:border-orange-500 outline-none"
                          placeholder="No budget found"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-semibold text-orange-700 mb-1">Est. GP ($)</label>
                        <input 
                          type="number"
                          value={newRecord.manualGP || ''}
                          onChange={e => setNewRecord({...newRecord, manualGP: Number(e.target.value)})} 
                          className="w-full text-sm p-2 border border-orange-300 bg-orange-50 rounded focus:border-orange-500 outline-none"
                          placeholder="No budget found"
                        />
                      </div>
                     </>
                   )}

                   {selectedProductHasBudget && (
                      <div className="col-span-2 flex items-center h-full pb-2">
                        <span className="text-xs text-green-600 bg-green-50 px-2 py-1 rounded border border-green-200">
                          Budget pricing applied automatically
                        </span>
                      </div>
                   )}

                   <div>
                     <button 
                       onClick={handleAddNew}
                       className="w-full bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold py-2 px-4 rounded shadow transition"
                     >
                       Add Entry
                     </button>
                   </div>
                </div>
             </div>
           )}

           <div className="bg-white rounded-xl shadow border border-blue-100 overflow-hidden">
             <table className="w-full text-left border-collapse">
               <thead className="bg-blue-50 text-blue-800 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-blue-100">Product</th>
                   <th className="p-4 border-b border-blue-100">Period</th>
                   <th className="p-4 border-b border-blue-100 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-blue-100 text-right">Sales</th>
                   <th className="p-4 border-b border-blue-100 text-right">GP</th>
                   <th className="p-4 border-b border-blue-100">Status</th>
                   <th className="p-4 border-b border-blue-100 text-center">Actions</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100 text-sm text-slate-700">
                 {sopData.map((row) => {
                   const isEditing = editingId === row.id;

                   return (
                     <tr key={row.id} className="hover:bg-slate-50 transition-colors">
                       <td className="p-4 font-medium text-slate-900">{row.product}</td>
                       <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>

                       {/* Qty Column */}
                       <td className="p-4 text-right font-mono">
                         {isEditing ? (
                           <input
                             type="number"
                             value={editQty}
                             onChange={(e) => setEditQty(Number(e.target.value))}
                             className="w-24 px-2 py-1 border border-blue-400 rounded focus:ring-2 focus:ring-blue-200 outline-none text-right"
                           />
                         ) : (
                           <span className="font-semibold">{row.qty.toLocaleString()}</span>
                         )}
                       </td>

                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.sales)}</td>
                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.gp)}</td>

                       <td className="p-4">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                           row.status === ForecastStatus.ARCHIVED ? 'bg-red-100 text-red-700' : 
                           row.status === ForecastStatus.APPROVED ? 'bg-green-100 text-green-700' :
                           'bg-yellow-100 text-yellow-700'
                         }`}>
                           {row.status}
                         </span>
                       </td>

                       {/* Actions Column */}
                       <td className="p-4 flex justify-center gap-2 relative">
                         {isEditing ? (
                           <div className="flex items-center gap-2 bg-white p-2 rounded-lg shadow-xl border border-slate-200 absolute right-12 z-20 -top-2">
                              <div className="flex flex-col">
                                <label className="text-[10px] text-slate-400 font-semibold mb-1 uppercase">Reason Code</label>
                                <select 
                                 value={editReason}
                                 onChange={(e) => setEditReason(e.target.value)}
                                 className="text-xs p-1.5 border border-slate-300 rounded w-40 outline-none focus:border-blue-500"
                                >
                                  <option value="">Select Reason...</option>
                                  {REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                                </select>
                              </div>
                              <div className="flex gap-1 mt-4">
                                <button onClick={handleSave} className="p-1.5 bg-green-50 hover:bg-green-100 text-green-700 rounded border border-green-200" title="Save"><Save size={14}/></button>
                                <button onClick={cancelEdit} className="p-1.5 bg-red-50 hover:bg-red-100 text-red-700 rounded border border-red-200" title="Cancel"><XCircle size={14}/></button>
                              </div>
                           </div>
                         ) : (
                           row.status !== ForecastStatus.ARCHIVED && (
                             <>
                               <button 
                                 onClick={() => startEdit(row)} 
                                 className="p-1.5 hover:bg-blue-50 text-blue-600 rounded transition-colors"
                                 title="Amend Forecast"
                               >
                                 <Edit2 size={16} />
                               </button>
                               <button 
                                 onClick={() => handleDelete(row)} 
                                 className="p-1.5 hover:bg-red-50 text-red-600 rounded transition-colors"
                                 title="Delete Record"
                               >
                                 <Trash2 size={16} />
                               </button>
                             </>
                           )
                         )}
                       </td>
                     </tr>
                   );
                 })}
                 {sopData.length === 0 && (
                   <tr>
                     <td colSpan={7} className="p-8 text-center text-slate-400 italic">No S&OP records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

        {/* Budget Section */}
        <div className="space-y-4">
           <div className="flex items-center gap-2 text-lg font-bold text-slate-600">
             <BookOpen className="h-5 w-5" />
             <h2>Budget Baseline</h2>
             <span className="text-xs font-normal text-slate-500 bg-slate-200 px-2 py-0.5 rounded-full">Reference Only</span>
           </div>

           <div className="bg-slate-50 rounded-xl border border-slate-200 overflow-hidden opacity-90">
             <table className="w-full text-left border-collapse">
               <thead className="bg-slate-100 text-slate-500 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-slate-200">Product</th>
                   <th className="p-4 border-b border-slate-200">Period</th>
                   <th className="p-4 border-b border-slate-200 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-slate-200 text-right">Sales</th>
                   <th className="p-4 border-b border-slate-200 text-right">GP</th>
                   <th className="p-4 border-b border-slate-200">Status</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-200 text-sm text-slate-600">
                 {budgetData.map((row) => (
                   <tr key={row.id}>
                     <td className="p-4 font-medium">{row.product}</td>
                     <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>
                     <td className="p-4 text-right font-mono">{row.qty.toLocaleString()}</td>
                     <td className="p-4 text-right">{formatCurrency(row.sales)}</td>
                     <td className="p-4 text-right">{formatCurrency(row.gp)}</td>
                     <td className="p-4">
                       <span className="px-2 py-1 rounded-full text-xs font-medium bg-slate-200 text-slate-600">
                         {row.status}
                       </span>
                     </td>
                   </tr>
                 ))}
                 {budgetData.length === 0 && (
                   <tr>
                     <td colSpan={6} className="p-8 text-center text-slate-400 italic">No Budget records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

      </div>
    </div>
  );
};

export default ReviewScreen;

import { ForecastRecord, VersionType, ForecastStatus } from '../types';

const CLIENTS = ['Alpha Corp', 'Beta Industries', 'Gamma Logistics'];
const PRODUCTS = ['Steel Coils', 'Aluminum Sheets', 'Copper Wire', 'Plastic Resins'];
const SECTIONS = ['Trader', 'Broker'];

// Define distinct characteristics for products to ensure KPIs shift when mix changes
const PRODUCT_SPECS: Record<string, { basePrice: number, margin: number }> = {
  'Steel Coils': { basePrice: 800, margin: 0.15 },      // Low margin, med price
  'Aluminum Sheets': { basePrice: 2200, margin: 0.25 }, // Med margin, high price
  'Copper Wire': { basePrice: 9000, margin: 0.08 },     // Low margin, very high price
  'Plastic Resins': { basePrice: 1200, margin: 0.35 }   // High margin, med price
};

export const generateMockData = (): ForecastRecord[] => {
  const data: ForecastRecord[] = [];
  const currentYear = new Date().getFullYear();

  let idCounter = 1;

  CLIENTS.forEach(client => {
    PRODUCTS.forEach(product => {
      const specs = PRODUCT_SPECS[product];

      // Create data for first 6 months
      for (let month = 1; month <= 6; month++) {
        // Add some random variance to quantity
        const baseQty = Math.floor(Math.random() * 50) + 10;

        // Add slight price fluctuation per month (±5%)
        const priceVariance = 1 + (Math.random() * 0.1 - 0.05);
        const actualPrice = specs.basePrice * priceVariance;

        const sales = baseQty * actualPrice;
        const gp = sales * specs.margin;

        // 1. Budget Version (The Baseline)
        data.push({
          id: `rec-${idCounter++}`,
          section: SECTIONS[Math.floor(Math.random() * SECTIONS.length)],
          client,
          country: 'USA',
          product,
          category: 'Raw Materials',
          month,
          year: currentYear,
          version: VersionType.BUDGET,
          qty: baseQty,
          sales: sales,
          gp: gp,
          salesPerson: 'John Doe',
          salesPersonEmail: 'john.doe@company.com',
          status: ForecastStatus.APPROVED
        });

        // 2. S&OP Version (Editable) - Initially matches budget
        data.push({
          id: `rec-${idCounter++}`,
          section: SECTIONS[0], // Simplified: all S&OP in Trader for demo consistency or match budget logic if needed
          client,
          country: 'USA',
          product,
          category: 'Raw Materials',
          month,
          year: currentYear,
          version: VersionType.SOP,
          qty: baseQty,
          sales: sales,
          gp: gp,
          salesPerson: 'John Doe',
          salesPersonEmail: 'john.doe@company.com',
          status: ForecastStatus.DRAFT
        });
      }
    });
  });

  return data;
};

import React, { useState, useMemo } from 'react';
import { ForecastRecord, VersionType, BudgetRatio, AuditLog, ForecastStatus } from '../types';
import { Edit2, Save, XCircle, Trash2, ArrowLeft, CheckCircle, TrendingUp, BookOpen, Plus, Calendar, DollarSign, Package, Percent, BarChart3, ArrowUp, ArrowDown, Minus } from 'lucide-react';

interface Props {
  data: ForecastRecord[];
  client: string;
  section: string;
  currentUserEmail: string;
  onUpdateData: (records: ForecastRecord[], auditLogs: AuditLog[]) => void;
  onBack: () => void;
  onSubmit: () => void;
}

const REASONS = [
  'Market Downturn',
  'Supply Chain Disruption',
  'New Business Won',
  'Customer Request',
  'Correction'
];

const ReviewScreen: React.FC<Props> = ({ 
  data, 
  client, 
  section, 
  currentUserEmail, 
  onUpdateData, 
  onBack, 
  onSubmit 
}) => {
  // Local state for editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editQty, setEditQty] = useState<number>(0);
  const [editReason, setEditReason] = useState<string>('');

  // Local state for adding
  const [isAdding, setIsAdding] = useState(false);
  const [newRecord, setNewRecord] = useState<{
    product: string;
    month: number;
    year: number;
    qty: number;
    manualSales?: number;
    manualGP?: number;
  }>({
    product: '',
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
    qty: 0
  });

  // Filter for relevant data
  const filteredData = useMemo(() => {
    return data.filter(d => d.client === client && d.section === section);
  }, [data, client, section]);

  // Derived lists for dropdowns
  const availableProducts = useMemo(() => Array.from(new Set(data.map(d => d.product))).sort(), [data]);
  const availableYears = useMemo(() => {
    const years = Array.from(new Set(data.map(d => d.year))).sort();
    return years.length ? years : [new Date().getFullYear()];
  }, [data]);

  // Calculate Budget Ratios (Sales per MT, GP per MT) for each product based on THIS CLIENT'S history
  const budgetRatios = useMemo(() => {
    const ratios = new Map<string, BudgetRatio>();

    const budgetItems = filteredData.filter(d => d.version === VersionType.BUDGET);
    const productGroups = new Map<string, { totalQty: number, totalSales: number, totalGP: number }>();

    budgetItems.forEach(item => {
      const current = productGroups.get(item.product) || { totalQty: 0, totalSales: 0, totalGP: 0 };
      current.totalQty += item.qty;
      current.totalSales += item.sales;
      current.totalGP += item.gp;
      productGroups.set(item.product, current);
    });

    productGroups.forEach((totals, product) => {
      if (totals.totalQty > 0) {
        ratios.set(product, {
          salesPerMT: totals.totalSales / totals.totalQty,
          gpPerMT: totals.totalGP / totals.totalQty
        });
      }
    });

    return ratios;
  }, [filteredData]);

  // Separate and Sort Data
  const sopData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.SOP)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  const budgetData = useMemo(() => {
    return filteredData
      .filter(d => d.version === VersionType.BUDGET)
      .sort((a, b) => {
        if (a.product !== b.product) return a.product.localeCompare(b.product);
        return a.month - b.month;
      });
  }, [filteredData]);

  // --- KPI CALCULATIONS ---
  const kpiStats = useMemo(() => {
    const calculateMetrics = (dataset: ForecastRecord[]) => {
      // Use fallback to 0 to prevent NaNs if data is malformed
      const totalQty = dataset.reduce((sum, item) => sum + (item.qty || 0), 0);
      const totalSales = dataset.reduce((sum, item) => sum + (item.sales || 0), 0);
      const totalGP = dataset.reduce((sum, item) => sum + (item.gp || 0), 0);
      return {
        qty: totalQty,
        sales: totalSales,
        gp: totalGP,
        gpPercent: totalSales > 0 ? (totalGP / totalSales) * 100 : 0,
        avgPrice: totalQty > 0 ? totalSales / totalQty : 0
      };
    };

    const current = calculateMetrics(sopData);
    const baseline = calculateMetrics(budgetData);

    return { current, baseline };
  }, [sopData, budgetData]);

  const renderKPICard = (
    title: string, 
    icon: React.ReactNode, 
    value: string, 
    currentRaw: number, 
    baselineRaw: number,
    isPercentage: boolean = false
  ) => {
    const isPositive = currentRaw >= baselineRaw;
    // For GP% and AvgPrice, we might want to color code differently? (Higher is better for GP/Price usually)
    // For now, Green = Increase, Red = Decrease relative to budget.

    const achievement = baselineRaw !== 0 
      ? Math.round((currentRaw / baselineRaw) * 100) 
      : (currentRaw > 0 ? 100 : 0);

    // For formatting trend text
    const trendColor = isPositive ? 'text-green-600' : 'text-red-600';
    const TrendIcon = isPositive ? ArrowUp : ArrowDown;
    const neutral = baselineRaw === 0;

    return (
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-between">
        <div className="flex justify-between items-start mb-2">
          <div className="text-slate-500 text-xs font-semibold uppercase tracking-wide">{title}</div>
          <div className={`p-1.5 rounded-lg ${isPositive ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
            {icon}
          </div>
        </div>
        <div>
          <div className="text-2xl font-bold text-slate-800">{value}</div>
          {!neutral ? (
             <div className={`flex items-center gap-1 text-xs font-medium mt-1 ${trendColor}`}>
               <TrendIcon size={12} strokeWidth={3} />
               <span>{achievement}% of Budget</span>
             </div>
          ) : (
            <div className="text-xs text-slate-400 mt-1 flex items-center gap-1">
              <Minus size={12} /> No Budget
            </div>
          )}
        </div>
      </div>
    );
  };
  // ------------------------

  // Actions
  const startEdit = (record: ForecastRecord) => {
    setEditingId(record.id);
    setEditQty(record.qty);
    setEditReason('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditQty(0);
    setEditReason('');
  };

  const handleSave = () => {
    if (!editingId || !editReason) {
      alert("Please select a Reason Code before saving.");
      return;
    }

    const record = data.find(d => d.id === editingId);
    if (!record) return;

    const ratio = budgetRatios.get(record.product) || { salesPerMT: 0, gpPerMT: 0 };

    // Recalculate based on Budget Logic if available, else keep ratio or warn
    const currentPrice = record.qty > 0 ? record.sales / record.qty : 0;
    const currentGPMargin = record.qty > 0 ? record.gp / record.qty : 0;

    const usedPrice = ratio.salesPerMT || currentPrice;
    const usedGP = ratio.gpPerMT || currentGPMargin;

    const newSales = editQty * usedPrice;
    const newGP = editQty * usedGP;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: editQty,
      sales: newSales,
      gp: newGP,
      status: ForecastStatus.DRAFT
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'AMEND',
      reasonCode: editReason,
      details: `Qty changed from ${record.qty} to ${editQty}.`
    };

    const newData = data.map(d => d.id === editingId ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);

    cancelEdit();
  };

  const handleDelete = (record: ForecastRecord) => {
    const reason = prompt("Select reason for deletion (Simulated dropdown):\n" + REASONS.join(', '));
    if (!reason) return;

    const updatedRecord: ForecastRecord = {
      ...record,
      qty: 0,
      sales: 0,
      gp: 0,
      status: ForecastStatus.ARCHIVED
    };

    const auditLog: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: record.id,
      product: record.product,
      actionType: 'DELETE',
      reasonCode: reason,
      details: `Record cleared/soft-deleted. Previous Qty: ${record.qty}`
    };

    const newData = data.map(d => d.id === record.id ? updatedRecord : d);
    onUpdateData(newData, [auditLog]);
  };

  // NEW: Handle Add Logic
  const handleAddNew = () => {
    if (!newRecord.product) { alert("Select a product"); return; }
    if (newRecord.qty <= 0) { alert("Qty > 0 required"); return; }

    const ratio = budgetRatios.get(newRecord.product);
    const hasBudget = ratio && ratio.salesPerMT > 0;

    let finalSales = 0;
    let finalGP = 0;

    if (hasBudget) {
      finalSales = newRecord.qty * ratio.salesPerMT;
      finalGP = newRecord.qty * ratio.gpPerMT;
    } else {
      finalSales = newRecord.manualSales || 0;
      finalGP = newRecord.manualGP || 0;
    }

    const newId = `new-${Date.now()}`;
    const newEntry: ForecastRecord = {
      id: newId,
      client,
      section,
      country: filteredData[0]?.country || 'Unknown',
      product: newRecord.product,
      category: filteredData.find(d => d.product === newRecord.product)?.category || 'General',
      month: newRecord.month,
      year: newRecord.year,
      version: VersionType.SOP,
      qty: newRecord.qty,
      sales: finalSales,
      gp: finalGP,
      salesPerson: filteredData[0]?.salesPerson || 'Unknown',
      salesPersonEmail: currentUserEmail,
      status: ForecastStatus.DRAFT
    };

    const log: AuditLog = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      userEmail: currentUserEmail,
      recordId: newId,
      product: newRecord.product,
      actionType: 'AMEND', // effectively adding is an amendment to the plan
      reasonCode: 'New Business', 
      details: `Added new record. Qty: ${newEntry.qty}`
    };

    onUpdateData([...data, newEntry], [log]);

    // Reset form
    setNewRecord({ ...newRecord, qty: 0, manualSales: 0, manualGP: 0 });
    setIsAdding(false);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  const formatNumber = (val: number) => {
    return new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(val);
  };

  // Check if selected product in Add Form has budget
  const selectedProductHasBudget = useMemo(() => {
    if (!newRecord.product) return true; // default hidden
    const r = budgetRatios.get(newRecord.product);
    return !!(r && r.salesPerMT > 0);
  }, [newRecord.product, budgetRatios]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-10 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold text-slate-800">{client}</h1>
            <p className="text-sm text-slate-500">Section: {section}</p>
          </div>
        </div>
        <button
          onClick={onSubmit}
          className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg font-semibold flex items-center gap-2 shadow-sm transition-colors"
        >
          <CheckCircle className="h-5 w-5" />
          Finish & Submit
        </button>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 overflow-auto max-w-[100vw] space-y-8">

        {/* KPI Dashboard */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 animate-in fade-in slide-in-from-top-4 duration-500">
          {renderKPICard(
            "Total Revenue", 
            <DollarSign size={18} />, 
            formatCurrency(kpiStats.current.sales), 
            kpiStats.current.sales, 
            kpiStats.baseline.sales
          )}
          {renderKPICard(
            "Total Volume (MT)", 
            <Package size={18} />, 
            formatNumber(kpiStats.current.qty), 
            kpiStats.current.qty, 
            kpiStats.baseline.qty
          )}
          {renderKPICard(
            "Gross Margin %", 
            <Percent size={18} />, 
            `${kpiStats.current.gpPercent.toFixed(2)}%`, 
            kpiStats.current.gpPercent, 
            kpiStats.baseline.gpPercent,
            true
          )}
          {renderKPICard(
            "Avg. Price / MT", 
            <BarChart3 size={18} />, 
            formatCurrency(kpiStats.current.avgPrice), 
            kpiStats.current.avgPrice, 
            kpiStats.baseline.avgPrice
          )}
        </div>

        {/* S&OP Section */}
        <div className="space-y-4">
           <div className="flex justify-between items-end">
             <div className="flex items-center gap-2 text-lg font-bold text-blue-800">
               <TrendingUp className="h-5 w-5" />
               <h2>Working Forecast (S&OP)</h2>
               <span className="text-xs font-normal text-blue-600 bg-blue-100 px-2 py-0.5 rounded-full">Editable</span>
             </div>

             {!isAdding && (
               <button 
                 onClick={() => setIsAdding(true)}
                 className="text-sm flex items-center gap-1 bg-blue-600 text-white px-3 py-1.5 rounded-lg hover:bg-blue-700 transition shadow-sm"
               >
                 <Plus size={16} /> Add Forecast
               </button>
             )}
           </div>

           {/* Add New Record Form */}
           {isAdding && (
             <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 animate-in fade-in slide-in-from-top-2">
                <div className="flex justify-between items-start mb-3">
                  <h3 className="text-sm font-bold text-blue-900 flex items-center gap-2">
                    <Plus size={14} /> New Entry
                  </h3>
                  <button onClick={() => setIsAdding(false)} className="text-slate-400 hover:text-slate-600"><XCircle size={18}/></button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-5 gap-4 items-end">
                   <div>
                     <label className="block text-xs font-semibold text-blue-800 mb-1">Product</label>
                     <select 
                       value={newRecord.product}
                       onChange={e => setNewRecord({...newRecord, product: e.target.value})}
                       className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                     >
                       <option value="">Select Product...</option>
                       {availableProducts.map(p => <option key={p} value={p}>{p}</option>)}
                     </select>
                   </div>

                   <div className="flex gap-2">
                      <div className="w-2/3">
                        <label className="block text-xs font-semibold text-blue-800 mb-1">Month</label>
                        <select 
                          value={newRecord.month}
                          onChange={e => setNewRecord({...newRecord, month: Number(e.target.value)})}
                          className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                        >
                          {Array.from({length: 12}, (_, i) => i + 1).map(m => (
                            <option key={m} value={m}>{new Date(2000, m-1, 1).toLocaleString('default', {month:'short'})}</option>
                          ))}
                        </select>
                      </div>
                      <div className="w-1/3">
                        <label className="block text-xs font-semibold text-blue-800 mb-1">Year</label>
                        <select 
                          value={newRecord.year}
                          onChange={e => setNewRecord({...newRecord, year: Number(e.target.value)})}
                          className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                        >
                          {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                      </div>
                   </div>

                   <div>
                     <label className="block text-xs font-semibold text-blue-800 mb-1">Quantity (MT)</label>
                     <input 
                       type="number" 
                       value={newRecord.qty}
                       onChange={e => setNewRecord({...newRecord, qty: Number(e.target.value)})}
                       className="w-full text-sm p-2 border border-blue-200 rounded focus:border-blue-500 outline-none"
                       placeholder="0"
                     />
                   </div>

                   {/* Dynamic Sales/GP fields if no budget */}
                   {!selectedProductHasBudget && (
                     <>
                      <div>
                        <label className="block text-xs font-semibold text-orange-700 mb-1">Est. Sales ($)</label>
                        <input 
                          type="number"
                          value={newRecord.manualSales || ''}
                          onChange={e => setNewRecord({...newRecord, manualSales: Number(e.target.value)})} 
                          className="w-full text-sm p-2 border border-orange-300 bg-orange-50 rounded focus:border-orange-500 outline-none"
                          placeholder="No budget found"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-semibold text-orange-700 mb-1">Est. GP ($)</label>
                        <input 
                          type="number"
                          value={newRecord.manualGP || ''}
                          onChange={e => setNewRecord({...newRecord, manualGP: Number(e.target.value)})} 
                          className="w-full text-sm p-2 border border-orange-300 bg-orange-50 rounded focus:border-orange-500 outline-none"
                          placeholder="No budget found"
                        />
                      </div>
                     </>
                   )}

                   {selectedProductHasBudget && (
                      <div className="col-span-2 flex items-center h-full pb-2">
                        <span className="text-xs text-green-600 bg-green-50 px-2 py-1 rounded border border-green-200">
                          Budget pricing applied automatically
                        </span>
                      </div>
                   )}

                   <div>
                     <button 
                       onClick={handleAddNew}
                       className="w-full bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold py-2 px-4 rounded shadow transition"
                     >
                       Add Entry
                     </button>
                   </div>
                </div>
             </div>
           )}

           <div className="bg-white rounded-xl shadow border border-blue-100 overflow-hidden">
             <table className="w-full text-left border-collapse">
               <thead className="bg-blue-50 text-blue-800 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-blue-100">Product</th>
                   <th className="p-4 border-b border-blue-100">Period</th>
                   <th className="p-4 border-b border-blue-100 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-blue-100 text-right">Sales</th>
                   <th className="p-4 border-b border-blue-100 text-right">GP</th>
                   <th className="p-4 border-b border-blue-100">Status</th>
                   <th className="p-4 border-b border-blue-100 text-center">Actions</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100 text-sm text-slate-700">
                 {sopData.map((row) => {
                   const isEditing = editingId === row.id;

                   return (
                     <tr key={row.id} className="hover:bg-slate-50 transition-colors">
                       <td className="p-4 font-medium text-slate-900">{row.product}</td>
                       <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>

                       {/* Qty Column */}
                       <td className="p-4 text-right font-mono">
                         {isEditing ? (
                           <input
                             type="number"
                             value={editQty}
                             onChange={(e) => setEditQty(Number(e.target.value))}
                             className="w-24 px-2 py-1 border border-blue-400 rounded focus:ring-2 focus:ring-blue-200 outline-none text-right"
                           />
                         ) : (
                           <span className="font-semibold">{row.qty.toLocaleString()}</span>
                         )}
                       </td>

                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.sales)}</td>
                       <td className="p-4 text-right text-slate-600">{formatCurrency(row.gp)}</td>

                       <td className="p-4">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                           row.status === ForecastStatus.ARCHIVED ? 'bg-red-100 text-red-700' : 
                           row.status === ForecastStatus.APPROVED ? 'bg-green-100 text-green-700' :
                           'bg-yellow-100 text-yellow-700'
                         }`}>
                           {row.status}
                         </span>
                       </td>

                       {/* Actions Column */}
                       <td className="p-4 flex justify-center gap-2 relative">
                         {isEditing ? (
                           <div className="flex items-center gap-2 bg-white p-2 rounded-lg shadow-xl border border-slate-200 absolute right-12 z-20 -top-2">
                              <div className="flex flex-col">
                                <label className="text-[10px] text-slate-400 font-semibold mb-1 uppercase">Reason Code</label>
                                <select 
                                 value={editReason}
                                 onChange={(e) => setEditReason(e.target.value)}
                                 className="text-xs p-1.5 border border-slate-300 rounded w-40 outline-none focus:border-blue-500"
                                >
                                  <option value="">Select Reason...</option>
                                  {REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                                </select>
                              </div>
                              <div className="flex gap-1 mt-4">
                                <button onClick={handleSave} className="p-1.5 bg-green-50 hover:bg-green-100 text-green-700 rounded border border-green-200" title="Save"><Save size={14}/></button>
                                <button onClick={cancelEdit} className="p-1.5 bg-red-50 hover:bg-red-100 text-red-700 rounded border border-red-200" title="Cancel"><XCircle size={14}/></button>
                              </div>
                           </div>
                         ) : (
                           row.status !== ForecastStatus.ARCHIVED && (
                             <>
                               <button 
                                 onClick={() => startEdit(row)} 
                                 className="p-1.5 hover:bg-blue-50 text-blue-600 rounded transition-colors"
                                 title="Amend Forecast"
                               >
                                 <Edit2 size={16} />
                               </button>
                               <button 
                                 onClick={() => handleDelete(row)} 
                                 className="p-1.5 hover:bg-red-50 text-red-600 rounded transition-colors"
                                 title="Delete Record"
                               >
                                 <Trash2 size={16} />
                               </button>
                             </>
                           )
                         )}
                       </td>
                     </tr>
                   );
                 })}
                 {sopData.length === 0 && (
                   <tr>
                     <td colSpan={7} className="p-8 text-center text-slate-400 italic">No S&OP records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

        {/* Budget Section */}
        <div className="space-y-4">
           <div className="flex items-center gap-2 text-lg font-bold text-slate-600">
             <BookOpen className="h-5 w-5" />
             <h2>Budget Baseline</h2>
             <span className="text-xs font-normal text-slate-500 bg-slate-200 px-2 py-0.5 rounded-full">Reference Only</span>
           </div>

           <div className="bg-slate-50 rounded-xl border border-slate-200 overflow-hidden opacity-90">
             <table className="w-full text-left border-collapse">
               <thead className="bg-slate-100 text-slate-500 text-xs uppercase font-semibold">
                 <tr>
                   <th className="p-4 border-b border-slate-200">Product</th>
                   <th className="p-4 border-b border-slate-200">Period</th>
                   <th className="p-4 border-b border-slate-200 text-right">Qty (MT)</th>
                   <th className="p-4 border-b border-slate-200 text-right">Sales</th>
                   <th className="p-4 border-b border-slate-200 text-right">GP</th>
                   <th className="p-4 border-b border-slate-200">Status</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-200 text-sm text-slate-600">
                 {budgetData.map((row) => (
                   <tr key={row.id}>
                     <td className="p-4 font-medium">{row.product}</td>
                     <td className="p-4">{row.year}-{String(row.month).padStart(2, '0')}</td>
                     <td className="p-4 text-right font-mono">{row.qty.toLocaleString()}</td>
                     <td className="p-4 text-right">{formatCurrency(row.sales)}</td>
                     <td className="p-4 text-right">{formatCurrency(row.gp)}</td>
                     <td className="p-4">
                       <span className="px-2 py-1 rounded-full text-xs font-medium bg-slate-200 text-slate-600">
                         {row.status}
                       </span>
                     </td>
                   </tr>
                 ))}
                 {budgetData.length === 0 && (
                   <tr>
                     <td colSpan={6} className="p-8 text-center text-slate-400 italic">No Budget records found.</td>
                   </tr>
                 )}
               </tbody>
             </table>
           </div>
        </div>

      </div>
    </div>
  );
};

export default ReviewScreen;
